/// fd slot a second time.
pub(crate) fn install_captured_fd(
    &mut self,
    captured: CapturedDetFd,
    newfd: RawFd,
    flags: OFlag,
) -> Result<Option<OpenFileId>, CapturedDetFdInstallError> {
    self.metadata().install_captured_fd(captured, newfd, flags)
}

