fn mountinfo_identity_order_from(contents: &[u8]) -> Result<Vec<u64>, Error> {
    use std::collections::BTreeSet;

    let rows = detcore_model::procfs::parse_mountinfo(contents)
        .ok_or_else(|| anyhow!("malformed /proc/self/mountinfo"))?;
