1451	    } else {
1452	        match std::str::from_utf8(task)
1453	            .ok()
1454	            .and_then(|s| s.parse::<i32>().ok())
1455	        {
1456	            Some(tid)
1457	                if (tid == state.pid || tid == state.tid) && tid.to_string().as_bytes() == task =>
1458	            {
1459	                tid
